import {comicDefaults} from './comic-format.js?v=20261025-release1';
export function printFields(prefix){
 const number=(key,label,min,max,step='0.5')=>`<label>${label}<input data-print-setting="${key}" id="${prefix}${key}" type="number" min="${min}" max="${max}" step="${step}" required></label>`;
 return `<div class="print-field-grid"><label>제본 방향<select data-print-setting="binding"><option value="right">일본 만화 · 우철 · 오른쪽 → 왼쪽</option><option value="left">좌철 · 왼쪽 → 오른쪽</option></select></label><label>본문 시작 면<select data-print-setting="firstSide"><option value="right">오른쪽 면에서 시작</option><option value="left">왼쪽 면에서 시작 · 일본 만화 기본</option></select></label></div><fieldset><legend>기본 테두리 · 안전 여백 mm</legend><div class="print-field-grid">${number('gutterMm','제본 안쪽',0,100)}${number('outerMm','바깥쪽',0,100)}${number('topMm','위쪽',0,100)}${number('bottomMm','아래쪽',0,100)}</div></fieldset><fieldset><legend>쪽 번호 · 책등</legend><label class="check"><input data-print-setting="folio" type="checkbox">본문 아래 바깥쪽에 쪽 번호 출력</label><div class="print-field-grid">${number('folioStart','시작 번호',1,9999,1)}${number('folioSizePt','글자 크기 pt',6,36,1)}${number('folioInsetMm','재단선에서 거리 mm',1,30)}${number('spineMm','책등 두께 mm',0,100,'0.1')}</div><small>책등 두께는 인쇄소의 용지·제본 사양에 맞춰 입력하세요.</small></fieldset>`;
}
export function fillPrintFields(root,values){const c=comicDefaults(values);root.querySelectorAll('[data-print-setting]').forEach(el=>{const v=c[el.dataset.printSetting];if(el.type==='checkbox')el.checked=!!v;else el.value=v;});}
export function readPrintFields(root){return Object.fromEntries([...root.querySelectorAll('[data-print-setting]')].map(el=>[el.dataset.printSetting,el.type==='checkbox'?el.checked:el.type==='number'?+el.value:el.value]));}
